CREATE TYPE "order_status" AS ENUM (
  'pending_payment',
  'paid',
  'completed',
  'cancelled'
);

CREATE TYPE "gift_card_status" AS ENUM (
  'available',
  'reserved',
  'sold',
  'blocked'
);

CREATE TABLE "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(254) UNIQUE NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "prices" (
  "nominal_usd" smallint PRIMARY KEY,
  "price_rub" decimal(12, 2) NOT NULL,
  CHECK (nominal_usd IN (1,2,3,4,5,10,15,20,25,30,40,50,100,200)),
  CHECK (price_rub > 0)
);

CREATE TABLE "orders" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "status" order_status NOT NULL DEFAULT 'pending_payment',
  "items" jsonb NOT NULL,
  "total_amount_rub" decimal(12, 2) NOT NULL,
  "reserved_until" timestamptz NOT NULL DEFAULT (now() + interval '15 minutes'),
  "paid_at" timestamptz,
  "email_sent_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CHECK (total_amount_rub > 0),
  CHECK (jsonb_typeof(items) = 'array' AND items <> '[]'::jsonb)
);

CREATE TABLE "gift_cards" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nominal_usd" smallint NOT NULL,
  "code_encrypted" bytea NOT NULL,
  "status" gift_card_status NOT NULL DEFAULT 'available',
  "order_id" bigint,
  "sale_price_rub" decimal(12, 2),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CHECK ((status IN ('reserved','sold') AND order_id IS NOT NULL AND sale_price_rub IS NOT NULL AND sale_price_rub > 0) OR (status IN ('available','blocked') AND order_id IS NULL AND sale_price_rub IS NULL))
);

CREATE INDEX ON "orders" ("user_id");

CREATE INDEX ON "orders" ("status", "reserved_until");

CREATE INDEX ON "gift_cards" ("nominal_usd", "status");

CREATE INDEX ON "gift_cards" ("order_id");

COMMENT ON COLUMN "orders"."items" IS '[{"nominal_usd":10,"quantity":2,"price_rub":1000.00}]';

ALTER TABLE "orders" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "gift_cards" ADD FOREIGN KEY ("nominal_usd") REFERENCES "prices" ("nominal_usd") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "gift_cards" ADD FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;
